{
  "name": "@arsxxi/iterative-dev-workflow",
  "version": "1.0.3",
  "description": "A structured 4-phase iterative development workflow for AI coding agents.",
  "keywords": ["opencode-plugin", "opencode", "kilocode", "kilo", "workflow", "methodology"],
  "license": "MIT",
  "author": {
    "name": "Clio",
    "url": "https://github.com/arsxxi/iterative-dev-workflow"
  },
  "homepage": "https://github.com/arsxxi/iterative-dev-workflow",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/arsxxi/iterative-dev-workflow.git"
  },
  "bugs": {
    "url": "https://github.com/arsxxi/iterative-dev-workflow/issues"
  },
  "main": "./.opencode/plugins/iterative-dev-workflow.mjs",
  "exports": {
    ".": "./.opencode/plugins/iterative-dev-workflow.mjs"
  },
  "bin": {
    "iterative-dev-workflow-install": "./bin/install-opencode-commands.mjs",
    "iterative-dev-workflow-install-kilo": "./bin/install-kilo-commands.mjs"
  },
  "scripts": {
    "postinstall": "node ./bin/install-opencode-commands.mjs || true"
  },
  "files": [
    "AGENTS.md",
    ".opencode/",
    ".kilo/",
    "kilo.jsonc",
    "commands/",
    "skills/",
    "bin/"
  ],
  "publishConfig": {
    "access": "public"
  }
}
